import math
import torch
import torch.nn as nn
import torch.nn.init as init
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor conv2d_cute_forward(torch::Tensor x,
                                   torch::Tensor w,
                                   c10::optional<torch::Tensor> b,
                                   int strideH, int strideW,
                                   int padH, int padW,
                                   int dilH, int dilW);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

template <typename T>
__global__ void conv2d_cute_kernel(
    const T* __restrict__ X,
    const T* __restrict__ W,
    const T* __restrict__ Bptr,
    T* __restrict__ Y,
    int N, int Cin, int H, int Win,
    int Cout, int KH, int KW,
    int strideH, int strideW,
    int padH, int padW,
    int dilH, int dilW,
    int Hout, int Wout,
    int TILE_IH, int TILE_IW,
    int gridH_tiles)
{
  constexpr int TILE_OH    = 16;
  constexpr int TILE_OW    = 16;
  constexpr int OW_PER_THREAD = 2;
  constexpr int Threads    = TILE_OH * TILE_OW;
  constexpr int CoPerBlock = 32;
  const int tid = threadIdx.x;
  const int ty  = tid / TILE_OW;
  const int tx  = tid % TILE_OW;
  const int n       = blockIdx.z;
  const int tile_h  = blockIdx.y % gridH_tiles;
  const int co_tile = blockIdx.y / gridH_tiles;
  const int co_base = co_tile * CoPerBlock;
  const int tile_w  = blockIdx.x;
  const int oh_base = tile_h * TILE_OH;
  const int ow_base = tile_w * (TILE_OW * OW_PER_THREAD);
  const int oh = oh_base + ty;
  const int ow0 = ow_base + tx;
  const int ow1 = ow0 + TILE_OW;
  const bool valid0 = (oh < Hout) && (ow0 < Wout);
  const bool valid1 = (oh < Hout) && (ow1 < Wout);
  const bool valid_any = valid0 || valid1;
  const int K = KH * KW;
  const int64_t sXc = (int64_t)H * Win;
  const int64_t sXh = (int64_t)Win;
  const int64_t sYc = (int64_t)Hout * Wout;
  const int64_t sYh = (int64_t)Wout;
  auto mX = make_tensor(
      make_gmem_ptr(X + (int64_t)n * Cin * H * Win),
      make_shape(Cin, H, Win),
      make_stride(sXc, sXh, Int<1>{})
  );
  auto mY = make_tensor(
      make_gmem_ptr(Y + (int64_t)n * Cout * Hout * Wout),
      make_shape(Cout, Hout, Wout),
      make_stride(sYc, sYh, Int<1>{})
  );
  auto mW = make_tensor(
      make_gmem_ptr(W),
      make_shape(Cout, Cin, KH, KW),
      make_stride(Cin * KH * KW, KH * KW, KW, Int<1>{})
  );
  extern __shared__ unsigned char smem_raw[];
  T* sW_ptr = reinterpret_cast<T*>(smem_raw);
  T* sX_ptr = sW_ptr + CoPerBlock * K;
  auto sW = make_tensor(
      make_smem_ptr(sW_ptr),
      make_shape(Int<CoPerBlock>{}, K),
      make_stride(K, Int<1>{})
  );
  const int ih_start = oh_base * strideH - padH;
  const int iw_start = ow_base * strideW - padW;
  const int tile_elems = TILE_IH * TILE_IW;
  float acc[CoPerBlock][OW_PER_THREAD];
  #pragma unroll
  for (int cc = 0; cc < CoPerBlock; ++cc) {
    int co = co_base + cc;
    float bval = (Bptr != nullptr && co < Cout) ? (float)Bptr[co] : 0.0f;
    acc[cc][0] = bval;
    acc[cc][1] = bval;
  }
  for (int c_in = 0; c_in < Cin; ++c_in) {
    for (int kk = tid; kk < CoPerBlock * K; kk += Threads) {
      int cc = kk / K;
      int kpos = kk % K;
      int co = co_base + cc;
      T wval = T(0);
      if (co < Cout) {
        int kh = kpos / KW;
        int kw = kpos - kh * KW;
        wval = mW(co, c_in, kh, kw);
      }
      sW(cc, kpos) = wval;
    }
    for (int idx = tid; idx < tile_elems; idx += Threads) {
      int ii = idx / TILE_IW;
      int jj = idx - ii * TILE_IW;
      int ih = ih_start + ii;
      int iw = iw_start + jj;
      T xval = T(0);
      if (ih >= 0 && ih < H && iw >= 0 && iw < Win) {
        xval = mX(c_in, ih, iw);
      }
      sX_ptr[idx] = xval;
    }
    __syncthreads();
    if (valid_any) {
      for (int kh = 0; kh < KH; ++kh) {
        int ih_local = ty * strideH + kh * dilH;
        const T* row_ptr = sX_ptr + ih_local * TILE_IW;
        for (int kw = 0; kw < KW; ++kw) {
          int iw_local0 = tx * strideW + kw * dilW;
          int iw_local1 = iw_local0 + TILE_OW * strideW;
          float xval0 = (float)row_ptr[iw_local0];
          float xval1 = (float)row_ptr[iw_local1];
          int kpos = kh * KW + kw;
          #pragma unroll
          for (int cc = 0; cc < CoPerBlock; ++cc) {
            float wval = (float)sW(cc, kpos);
            acc[cc][0] += xval0 * wval;
            acc[cc][1] += xval1 * wval;
          }
        }
      }
    }
    __syncthreads();
  }
  if (valid0 || valid1) {
    #pragma unroll
    for (int cc = 0; cc < CoPerBlock; ++cc) {
      int co = co_base + cc;
      if (co >= Cout) continue;
      if (valid0) mY(co, oh, ow0) = static_cast<T>(acc[cc][0]);
      if (valid1) mY(co, oh, ow1) = static_cast<T>(acc[cc][1]);
    }
  }
}
torch::Tensor conv2d_cute_forward(torch::Tensor x,
                                   torch::Tensor w,
                                   c10::optional<torch::Tensor> b,
                                   int strideH, int strideW,
                                   int padH, int padW,
                                   int dilH, int dilW) {
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(w.is_cuda(), "w must be CUDA");
  if (b.has_value()) TORCH_CHECK(b.value().is_cuda(), "bias must be CUDA if provided");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(w.scalar_type() == at::kFloat, "w must be float32");
  if (b.has_value()) TORCH_CHECK(b.value().scalar_type() == at::kFloat, "bias must be float32");
  TORCH_CHECK(x.dim() == 4, "x must be [N, Cin, H, W]");
  TORCH_CHECK(w.dim() == 4, "w must be [Cout, Cin, KH, KW]");
  int64_t N    = x.size(0);
  int64_t Cin  = x.size(1);
  int64_t H    = x.size(2);
  int64_t Win  = x.size(3);
  int64_t Cout = w.size(0);
  TORCH_CHECK(w.size(1) == Cin, "w.size(1) must equal Cin");
  int64_t KH   = w.size(2);
  int64_t KW   = w.size(3);
  TORCH_CHECK(strideH > 0 && strideW > 0, "stride must be > 0");
  TORCH_CHECK(dilH > 0 && dilW > 0, "dilation must be > 0");
  TORCH_CHECK(padH >= 0 && padW >= 0, "padding must be >= 0");
  int64_t Hout = (H + 2 * padH - dilH * (KH - 1) - 1) / strideH + 1;
  int64_t Wout = (Win + 2 * padW - dilW * (KW - 1) - 1) / strideW + 1;
  TORCH_CHECK(Hout > 0 && Wout > 0, "Invalid output size computed");
  auto x_c = x.contiguous();
  auto w_c = w.contiguous();
  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (b.has_value()) {
    b_c = b.value().contiguous();
    TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == Cout, "bias must be [Cout]");
    b_ptr = b_c.data_ptr<float>();
  }
  auto y = torch::empty({N, Cout, Hout, Wout}, x.options());
  constexpr int TILE_OH    = 16;
  constexpr int TILE_OW    = 16;
  constexpr int OW_PER_THREAD = 2;
  constexpr int Threads    = TILE_OH * TILE_OW;
  constexpr int CoPerBlock = 32;
  int TILE_IH = (int)((TILE_OH - 1) * strideH + (KH - 1) * dilH + 1);
  int TILE_IW = (int)(((TILE_OW * OW_PER_THREAD) - 1) * strideW + (KW - 1) * dilW + 1);
  int gridW_tiles = (int)((Wout + (TILE_OW * OW_PER_THREAD) - 1) / (TILE_OW * OW_PER_THREAD));
  int gridH_tiles = (int)((Hout + TILE_OH - 1) / TILE_OH);
  int co_tiles    = (int)((Cout + CoPerBlock - 1) / CoPerBlock);
  dim3 block(Threads);
  dim3 grid(
      (unsigned)gridW_tiles,
      (unsigned)(gridH_tiles * co_tiles),
      (unsigned)N
  );
  size_t smem_bytes = (size_t)(CoPerBlock * (int)(KH * KW) + TILE_IH * TILE_IW) * sizeof(float);
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  conv2d_cute_kernel<float><<<grid, block, smem_bytes, stream>>>(
      x_c.data_ptr<float>(),
      w_c.data_ptr<float>(),
      b_ptr,
      y.data_ptr<float>(),
      (int)N, (int)Cin, (int)H, (int)Win,
      (int)Cout, (int)KH, (int)KW,
      strideH, strideW,
      padH, padW,
      dilH, dilW,
      (int)Hout, (int)Wout,
      TILE_IH, TILE_IW,
      gridH_tiles
  );
  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv2d_cute_kernel launch failed: ", cudaGetErrorString(err));
  return y;
}
"""

conv2d_ext = load_inline(
    name="cute_conv2d_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["conv2d_cute_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Standard 2D convolution with asymmetric kernel, dilation, and padding,
    implemented with a single custom CUDA kernel using CuTe.
    """
    def __init__(self,
                 in_channels: int,
                 out_channels: int,
                 kernel_size: tuple,
                 stride: int = 1,
                 padding: tuple = (0, 0),
                 dilation: tuple = (1, 1),
                 bias: bool = False) -> None:
        super().__init__()

        self.in_channels = int(in_channels)
        self.out_channels = int(out_channels)
        self.kernel_size = (int(kernel_size[0]), int(kernel_size[1]))
        self.stride = int(stride)
        self.padding = (int(padding[0]), int(padding[1]))
        self.dilation = (int(dilation[0]), int(dilation[1]))

        Cin = self.in_channels
        Cout = self.out_channels
        KH, KW = self.kernel_size

        self.weight = nn.Parameter(torch.empty(Cout, Cin, KH, KW))
        if bias:
            self.bias = nn.Parameter(torch.empty(Cout))
        else:
            self.register_parameter("bias", None)

        self.reset_parameters()
        self._ext = conv2d_ext

    def reset_parameters(self):
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in = self.in_channels * self.kernel_size[0] * self.kernel_size[1]
            bound = 1.0 / math.sqrt(fan_in) if fan_in > 0 else 0.0
            init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.conv2d_cute_forward(
            x.contiguous(),
            self.weight.contiguous(),
            self.bias if self.bias is not None else None,
            self.stride, self.stride,
            self.padding[0], self.padding[1],
            self.dilation[0], self.dilation[1],
        )

